def inside_out(x):
    def transform_word(word):
        n = len(word)
        if n <= 2:
            return word

        result = [''] * n
        left = 0
        right = n - 1

        for i in range(n // 2):
            result[i] = word[right]
            result[n - 1 - i] = word[left]
            left += 1
            right -= 1

        if n % 2 == 1:
            result[n // 2] = word[n // 2]

        return ''.join(result)

    words = x.split()
    transformed_words = [transform_word(word) for word in words]
    return ' '.join(transformed_words)
